          var t = c.tags[j];
          if (!t || !t.position) continue;
          var lit = String(t.tag).replace(/^#/, "");
          if (fmRange && t.position.start.line >= fmRange.a && t.position.start.line <= fmRange.b) continue;
          var repl = segReplace(lit, oldSegs, newSegs);
          if (repl == null) continue;
